<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Affiliate,AffiliateReferral,User};use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class AffiliateController extends Controller{public function index(){return view('admin.affiliates.index',['affiliates'=>Affiliate::withCount('referrals')->latest()->get(),'pendingPayout'=>AffiliateReferral::where('status','approved')->sum('commission_amount'),'customers'=>User::where('role','!=','admin')->orderBy('name')->get(['id','name','email'])]);}public function store(Request $r){$d=$this->data($r);$d['code']=$d['code']?:strtoupper(Str::random(8));Affiliate::create($d);return back()->with('success','Affiliate created.');}public function update(Request $r,Affiliate $affiliate){$affiliate->update($this->data($r,$affiliate));return back()->with('success','Affiliate updated.');}public function destroy(Affiliate $affiliate){$affiliate->delete();return back()->with('success','Affiliate removed.');}public function pay(AffiliateReferral $referral){$referral->update(['status'=>'paid','paid_at'=>now()]);return back()->with('success','Affiliate commission marked paid.');}private function data(Request $r,?Affiliate $a=null){return $r->validate(['user_id'=>'nullable|exists:users,id','name'=>'required|string|max:150','email'=>'required|email|max:255','code'=>['nullable','string','max:50',Rule::unique('affiliates','code')->ignore($a?->id)],'commission_rate'=>'required|numeric|min:0|max:100','status'=>'required|in:active,paused,disabled']);}}

